import puppeteer from '/tmp/qs-hf-probe/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js';
import fs from 'node:fs/promises';
const browser = await puppeteer.launch({executablePath:'/home/djn12313/.cache/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-linux64/chrome-headless-shell',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
try {
 const page = await browser.newPage();
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.setRequestInterception(true);
 page.on('request',r=>r.url().startsWith('file:') ? r.continue() : r.abort());
 await fs.mkdir('artifacts',{recursive:true});
 const observations=[];
 for (const viewport of [{width:1280,height:900},{width:390,height:844}]) {
  await page.setViewport(viewport);
  await page.goto('file:///tmp/qs-frontend-v2-task-n57C3i/index.html');
  await page.screenshot({path:"'`artifacts/membership-${viewport.width}.png`,fullPage:true});
  observations.push(await page.evaluate(()=>({width:innerWidth,overflow:document.documentElement.scrollWidth>innerWidth,headings:[...document.querySelectorAll('"'h1,h2,h3')].map(e=>e.textContent),controls:[...document.querySelectorAll('input[type=email],button')].map(e=>({id:e.id,font:getComputedStyle(e).fontFamily,radius:getComputedStyle(e).borderRadius})),paper:getComputedStyle(document.body).backgroundColor,primary:getComputedStyle(document.querySelector('.join-panel')).backgroundColor,details:document.getElementById('details-link').getAttribute('href')})));
  await page.click('#join-button');
  if(await page.evaluate(()=>Boolean(window.__events?.length)))throw Error('Empty form emitted event');
  await page.type('#member-email','invalid');
  await page.click('#join-button');
  if(await page.evaluate(()=>Boolean(window.__events?.length)))throw Error('Invalid email emitted event');
  await page."'$eval('"'#member-email',el=>el.value='');
  await page.type('#member-email','member@example.com');
  await page.focus('#member-email');
  await page.keyboard.press('Tab');
  const focus = await page.evaluate(()=>({id:document.activeElement.id,outline:getComputedStyle(document.activeElement).outlineStyle}));
  if(focus.id"'!=='"'join-button'||focus.outline==='none')throw Error('Keyboard focus failed');
  await page.keyboard.press('Enter');
  const result=await page.evaluate(()=>({message:document.getElementById('form-message').textContent,events:window.__events,url:location.href}));
  if(result.message"'!=='"'Ready to continue with Family membership.'||JSON.stringify(result.events)"'!=='"'[{\"name\":\"join_started\",\"plan\":\"family\"}]'||"'!result.url.startsWith('"'file:'))throw Error('Submission failed');
  observations.push({width:viewport.width,keyboard:focus,form:result});
 }
 await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);
 observations.push(await page.evaluate(()=>({reducedMotion:{scroll:getComputedStyle(document.documentElement).scrollBehavior,buttonTransition:getComputedStyle(document.getElementById('join-button')).transitionDuration},ids:['site-header','site-footer','membership-panel','membership-title','price','member-count','annual-visits','founded','join-form','member-email','join-button','form-message','details-link'].every(id=>document.getElementById(id))})));
 await page.goto('file:///tmp/qs-frontend-v2-task-n57C3i/index.html');
 await page.keyboard.press('Tab');
 if(await page.evaluate(()=>document.activeElement.textContent)"'!=='"'Skip to content')throw Error('Skip link not first');
 if(errors.length)throw Error(errors.join('\\n'));
 if(observations.some(o=>o.overflow))throw Error('Horizontal overflow');
 console.log(JSON.stringify({passed:true,observations,errors,screenshots:['artifacts/membership-1280.png','artifacts/membership-390.png']},null,2));
} finally {await browser.close();}
NODE"

